 q=pd.Series(q).dropna();print(lab,'dates',len(q),'IC',round(q.mean(),6),'ICIR',round(q.mean()/q.std(ddof=1),6) if len(q)>1 else None,'hit',round((q>0).mean(),4))
rank=sig.rank(axis=1,pct=True); t=[]
for a,b in zip(rank.index[:-1],rank.index[1:]):
 if (b-a).days<=10:
