 if len(q)>=8 and q.iloc[:,1].var()>1e-14:
  b=np.cov(q.iloc[:,0],q.iloc[:,1],ddof=1)[0,1]/q.iloc[:,1].var()
  z.loc[q.index]=q.iloc[:,0]-b*q.iloc[:,1]
