 z=pd.Series(vals,index=dates).dropna();print('h',h,'IC %.5f ICIR %.5f dates %d avgN %.2f hit %.3f'%(z.mean(),z.mean()/z.std(ddof=1)*np.sqrt(len(z)),len(z),np.mean(ns[:len(z)]),(z>0).mean()))
